// Compatible with the existing app.js call signature and reroll button.
function readingFor(animal, variant, name, index) {
  const options = dailyReadings[name];
  if (!options) throw new Error("Missing readings for " + name);
  const n = ((index % options.length) + options.length) % options.length;
  return { ...options[n] };
}

